/* Workflow designer: declarative project settings, no executable template code. */
Workflow.normalize(state);
let designMode=false,draggedWorkflow=null;
function pointerWorkflowDrag(element,payload){
 element.draggable=false;element.style.touchAction='none';let drag=null;
 element.onpointerdown=e=>{if(e.button!==0)return;drag={x:e.clientX,y:e.clientY,active:false,target:null};element.setPointerCapture(e.pointerId);};
 element.onpointermove=e=>{if(!drag)return;if(!drag.active&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)<7)return;if(!drag.active){drag.active=true;drag.ghost=document.createElement('div');drag.ghost.className='workflow-drag-ghost';drag.ghost.textContent=payload.id?node(payload.id).name:Workflow.types[payload.type];document.body.append(drag.ghost);}e.preventDefault();drag.ghost.style.left=(e.clientX+14)+'px';drag.ghost.style.top=(e.clientY+14)+'px';const hit=document.elementFromPoint(e.clientX,e.clientY);const candidate=hit?.closest('[data-node],[data-collapse],.flow-lane');if(drag.target!==candidate){drag.target?.classList.remove('drop-target');drag.target=candidate;candidate?.classList.add('drop-target');}const scroll=$('.flow-scroll');if(scroll){const rect=scroll.getBoundingClientRect();if(e.clientY>rect.bottom-35)scroll.scrollTop+=18;else if(e.clientY<rect.top+35)scroll.scrollTop-=18;}};
 const end=e=>{if(!drag)return;const current=drag;drag=null;current.ghost?.remove();current.target?.classList.remove('drop-target');if(!current.active)return;const suppress=event=>{event.preventDefault();event.stopImmediatePropagation()};document.addEventListener('click',suppress,true);setTimeout(()=>document.removeEventListener('click',suppress,true),0);if(e.type==='pointercancel'||!current.target)return;const target=current.target;const before=target.dataset.node;const stage=before?node(before).stage:target.dataset.collapse!==undefined?+target.dataset.collapse:[...document.querySelectorAll('.flow-lane')].indexOf(target);if(stage<0)return;if(payload.id&&payload.id!==before)moveWorkflowNode(payload.id,stage,before);else if(payload.type)createWorkflowNode(payload.type,stage,before);};
 element.onpointerup=end;element.onpointercancel=end;
}
const originalRenderTree=renderTree,originalRenderDetail=renderDetail,originalLayout=diagramLayout;
diagramLayout=function(){
 const columns=stageNames.map((_,i)=>state.nodes.filter(n=>n.stage===i).sort((a,b)=>(a.order??state.nodes.indexOf(a))-(b.order??state.nodes.indexOf(b))));
 const positions={};columns.forEach((ns,col)=>{if(!collapsedStages.has(col))ns.forEach((n,row)=>positions[n.id]={x:40+col*310,y:248+row*134,col});});
 return {columns,positions,height:Math.max(1,...columns.map((ns,i)=>collapsedStages.has(i)?0:ns.length))*134+284};
};
async function commitWorkflow(backup,message){try{validate(state);log(message);await persist();return true}catch(e){state=backup;render();toast('Chưa lưu: '+e.message);return false}}
async function moveWorkflowNode(id,stage,beforeId=null){const n=node(id);if(!n)return;const backup=structuredClone(state),oldStage=n.stage;n.stage=stage;const ordered=state.nodes.filter(x=>x.stage===stage&&x.id!==id).sort((a,b)=>(a.order??0)-(b.order??0));const index=ordered.findIndex(x=>x.id===beforeId);ordered.splice(index<0?ordered.length:index,0,n);ordered.forEach((x,i)=>x.order=i);collapsedStages.delete(stage);if(await commitWorkflow(backup,'Di chuyển '+n.name+' sang '+stageNames[stage]))toast('Đã lưu vị trí hồ sơ'+(oldStage!==stage?' và đánh giá lại timeline':''));}
function createWorkflowNode(type,stage=0,beforeId=null){const id='step_'+crypto.randomUUID().slice(0,8);const draft={id,name:Workflow.types[type]||'Hồ sơ mới',type,stage,folder:['01_ChuanBi','02_ThiCong','03_HoanCong'][stage]+'/HoSo/'+id,deps:[],required:true,order:state.nodes.length,dateRules:[],symbol:'▤',status:'missing',date:'',code:'',issuer:'',note:'',startDate:'',dueDate:'',completedAt:'',files:[]};editWorkflowNode(draft,true,beforeId);}
renderTree=function(){originalRenderTree();const toolbar=$('.flow-toolbar');if(!toolbar)return;const controls=$('.flow-controls');const design=document.createElement('button');design.id='designWorkflow';design.textContent=designMode?'Xong thiết kế':'Thiết kế quy trình';design.setAttribute('aria-pressed',designMode);design.onclick=()=>{designMode=!designMode;renderTree()};controls.prepend(design);
 const all=Workflow.alerts(state,Workflow.today(),complete);const command=document.createElement('div');command.className='workflow-command';command.innerHTML=`<span>${designMode?'Kéo một bước vào giai đoạn; kéo thẻ để đổi thứ tự.':'Quy trình của dự án · Quy tắc được lưu cùng hồ sơ'}</span><div><button id="workflowAlerts">Cảnh báo <b>${all.length}</b></button><button id="workflowTemplate">Template</button></div>`;$('.flow-legend-bar').after(command);$('#workflowAlerts').onclick=showWorkflowAlerts;$('#workflowTemplate').onclick=showWorkflowTemplate;
 if(designMode){const palette=document.createElement('div');palette.className='workflow-palette';palette.innerHTML=Object.entries(Workflow.types).map(([type,label])=>`<button draggable="true" data-palette="${type}" title="Kéo vào giai đoạn hoặc bấm để thêm">＋ ${label}</button>`).join('');command.after(palette);palette.querySelectorAll('[data-palette]').forEach(b=>{b.onclick=()=>createWorkflowNode(b.dataset.palette);b.ondragstart=e=>{draggedWorkflow={type:b.dataset.palette};e.dataTransfer.setData('text/plain',b.dataset.palette);e.dataTransfer.effectAllowed='copy'};b.ondragend=()=>draggedWorkflow=null;pointerWorkflowDrag(b,{type:b.dataset.palette});});}
 document.querySelectorAll('[data-node]').forEach(b=>{const n=node(b.dataset.node),findings=all.filter(a=>a.nodeId===n.id);if(findings.length){const badge=document.createElement('span');badge.className='workflow-alert-badge '+(findings.some(a=>a.severity==='error')?'error':'');badge.textContent='! '+findings.length;badge.title=findings.map(a=>a.message).join('\n');b.append(badge);}if(n.required===false)b.classList.add('is-optional');if(!designMode)return;b.draggable=true;b.classList.add('is-draggable');b.title='Kéo để di chuyển · Bấm để cấu hình';b.onclick=()=>editWorkflowNode(n);b.ondragstart=e=>{draggedWorkflow={id:n.id};e.dataTransfer.setData('text/plain',n.id);e.dataTransfer.effectAllowed='move'};b.ondragend=()=>{draggedWorkflow=null;document.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-target'))};attachDrop(b,n.stage,n.id);pointerWorkflowDrag(b,{id:n.id});});
 if(designMode){document.querySelectorAll('[data-collapse]').forEach(b=>attachDrop(b,+b.dataset.collapse));document.querySelectorAll('.flow-lane').forEach((b,i)=>attachDrop(b,i));}
 function attachDrop(target,stage,beforeId){target.ondragover=e=>{if(!draggedWorkflow)return;e.preventDefault();e.dataTransfer.dropEffect=draggedWorkflow.id?'move':'copy';target.classList.add('drop-target')};target.ondragleave=()=>target.classList.remove('drop-target');target.ondrop=e=>{e.preventDefault();e.stopPropagation();target.classList.remove('drop-target');const item=draggedWorkflow;draggedWorkflow=null;if(!item)return;if(item.id&&item.id!==beforeId)moveWorkflowNode(item.id,stage,beforeId);else if(item.type)createWorkflowNode(item.type,stage,beforeId)}}
 const inspector=$('#detail');if(inspector)inspector.style.top=$('.flow-scroll').offsetTop+'px';
};
renderDetail=function(){originalRenderDetail();const n=node(selected),holder=document.createElement('div');holder.className='workflow-detail';const f=Workflow.dateFindings(n,state.nodes);holder.innerHTML=`<strong>LỊCH & RÀNG BUỘC</strong><p>${n.startDate?'Bắt đầu: '+esc(n.startDate)+'<br>':''}${n.dueDate?'Hạn: '+esc(n.dueDate)+'<br>':''}${n.completedAt?'Hoàn tất: '+esc(n.completedAt)+'<br>':''}${!n.startDate&&!n.dueDate&&!n.completedAt?'Chưa đặt lịch.':''}</p>${f.map(x=>`<div class="rule-warning">${x.blocking?'Bắt buộc · ':'Nhắc việc · '}${esc(x.message)}</div>`).join('')}<button id="configureWorkflowNode">Cấu hình bước & ngày tháng</button>`;$('#detail').append(holder);$('#configureWorkflowNode').onclick=()=>editWorkflowNode(n);};
function ruleRow(rule={sourceId:'',sourceField:'date',targetField:'date',relation:'after',days:0,blocking:true}){return `<div class="date-rule"><div class="rule-row"><label>Ngày của bước này<select data-rule="targetField">${options(Workflow.fields,rule.targetField)}</select></label><label>Quan hệ<select data-rule="relation"><option value="after" ${rule.relation==='after'?'selected':''}>Sau hoặc bằng</option><option value="before" ${rule.relation==='before'?'selected':''}>Trước hoặc bằng</option></select></label></div><label>Hồ sơ đối chiếu<select data-rule="sourceId" required><option value="">Chọn hồ sơ</option>${state.nodes.filter(n=>n.id!==$('#workflowForm')?.dataset.node).map(n=>`<option value="${n.id}" ${n.id===rule.sourceId?'selected':''}>${esc(n.name)}</option>`).join('')}</select></label><div class="rule-row"><label>Ngày nguồn<select data-rule="sourceField">${options(Workflow.fields,rule.sourceField)}</select></label><label>Cách ít nhất (ngày)<input data-rule="days" type="number" min="0" max="3650" value="${rule.days}"></label></div><label class="check-label"><input data-rule="blocking" type="checkbox" ${rule.blocking?'checked':''}> Bắt buộc để hoàn tất</label><button type="button" class="remove-rule">Bỏ quy tắc</button></div>`;}
function options(values,selected){return Object.entries(values).map(([v,label])=>`<option value="${v}" ${v===selected?'selected':''}>${esc(label)}</option>`).join('')}
function editWorkflowNode(n,isNew=false,beforeId=null){showModal(isNew?'Thêm bước vào quy trình':'Cấu hình bước hồ sơ',`<form id="workflowForm" data-node="${n.id}"><label>Tên bước<input name="name" required maxlength="120" value="${esc(n.name)}"></label><div class="form-grid"><label>Loại bước<select name="type">${options(Workflow.types,n.type||'task')}</select></label><label>Giai đoạn<select name="stage">${stageNames.map((s,i)=>`<option value="${i}" ${i===n.stage?'selected':''}>${s}</option>`).join('')}</select></label></div><label>Thứ tự trong giai đoạn (từ 0)<input type="number" name="order" min="0" max="1000" required value="${n.order??0}"></label><label class="check-label"><input type="checkbox" name="required" ${n.required!==false?'checked':''}> Tính vào điều kiện hoàn tất giai đoạn</label><fieldset><legend>Hồ sơ phải hoàn tất trước bước này</legend><div class="dependency-picker">${state.nodes.filter(x=>x.id!==n.id).map(x=>`<label class="check-label"><input type="checkbox" name="deps" value="${x.id}" ${n.deps.includes(x.id)?'checked':''}> ${esc(x.name)}</label>`).join('')}</div></fieldset><fieldset><legend>Ngày tháng của bước hồ sơ</legend><div class="form-grid">${Object.entries(Workflow.fields).map(([key,label])=>`<label>${label}<input type="date" name="${key}" value="${esc(n[key]||'')}"></label>`).join('')}</div></fieldset><fieldset><legend>Ràng buộc ngày trước / sau</legend><p class="rule-help">0 ngày cho phép cùng ngày; 1 ngày yêu cầu khác ngày. Quy tắc bắt buộc sẽ chặn hoàn tất nếu sai hoặc thiếu ngày, kể cả khi bạn tắt hiển thị cảnh báo.</p><div id="dateRules"></div><button type="button" class="button" id="addDateRule">＋ Thêm ràng buộc</button></fieldset><p id="workflowFormError" class="error" role="alert"></p><div class="modal-actions"><button class="button primary">${isNew?'Thêm bước':'Lưu cấu hình'}</button></div></form>`);$('#dateRules').innerHTML=(n.dateRules||[]).map(ruleRow).join('');const wire=()=>document.querySelectorAll('.remove-rule').forEach(b=>b.onclick=()=>b.closest('.date-rule').remove());wire();$('#addDateRule').onclick=()=>{$('#dateRules').insertAdjacentHTML('beforeend',ruleRow());wire()};$('#workflowForm').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),backup=structuredClone(state);const rules=[...document.querySelectorAll('.date-rule')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-rule]')].map(el=>[el.dataset.rule,el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value])));const values={name:form.get('name').trim(),type:form.get('type'),stage:Number(form.get('stage')),required:form.has('required'),order:Number(form.get('order')),deps:form.getAll('deps'),dateRules:rules};for(const key of Object.keys(Workflow.fields))values[key]=form.get(key);if(isNew)state.nodes.push({...n,...values});else Object.assign(node(n.id),values);try{validate(state)}catch(err){state=backup;$('#workflowFormError').textContent=err.message;return}if(await commitWorkflow(backup,(isNew?'Thêm bước ':'Cấu hình bước ')+values.name)){selected=n.id;collapsedStages.delete(values.stage);$('#modal').close();if(isNew&&beforeId)await moveWorkflowNode(n.id,values.stage,beforeId);render();toast('Đã lưu bước và kiểm tra lại điều kiện')}};}
function showWorkflowAlerts(){const cfg={...Workflow.defaults,...state.alertSettings},alerts=Workflow.alerts(state,Workflow.today(),complete);showModal('Cảnh báo & nhắc việc',`<form id="alertSettings"><div class="alert-toggles">${Object.entries({dueSoon:'Sắp đến hạn',overdue:'Quá hạn',dateOrder:'Ngày không đúng thứ tự',missingDate:'Thiếu ngày để đối chiếu',blocked:'Thiếu hồ sơ phụ thuộc'}).map(([key,label])=>`<label class="check-label"><input name="${key}" type="checkbox" ${cfg[key]?'checked':''}>${label}</label>`).join('')}</div><label>Nhắc trước hạn (ngày)<input name="leadDays" type="number" min="0" max="365" value="${cfg.leadDays}" required></label><p class="notice">Cảnh báo hiển thị trong ứng dụng khi mở hoặc cập nhật hồ sơ. Chưa gửi email hay thông báo khi đóng web. Tắt hiển thị không bỏ điều kiện bắt buộc.</p><div class="modal-actions"><button class="button primary">Lưu tùy chọn</button></div></form><h3 class="alerts-title">${alerts.length} cảnh báo hiện tại</h3>${alerts.map(a=>`<button class="alert-item ${a.severity}" data-alert-node="${a.nodeId}"><strong>${esc(node(a.nodeId).name)}</strong><span>${esc(a.message)}</span></button>`).join('')||'<p>Không có cảnh báo theo tùy chọn hiện tại.</p>'}`);$('#alertSettings').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target),backup=structuredClone(state);state.alertSettings={leadDays:Number(data.get('leadDays'))};for(const key of Object.keys(Workflow.defaults).filter(k=>k!=='leadDays'))state.alertSettings[key]=data.has(key);if(await commitWorkflow(backup,'Cập nhật tùy chọn cảnh báo'))showWorkflowAlerts();};document.querySelectorAll('[data-alert-node]').forEach(b=>b.onclick=()=>{$('#modal').close();focusDossier(b.dataset.alertNode)})}
function downloadTemplate(value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='quy-trinh.template.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function showWorkflowTemplate(){showModal('Template quy trình dùng chung',`<p>Template gồm loại bước, giai đoạn, quan hệ phụ thuộc, thứ tự, quy tắc ngày và tùy chọn cảnh báo.</p><div class="notice">Không xuất tài liệu, thông tin văn bản, ngày thực tế, trạng thái hoàn tất hay API key. Tên bước do bạn đặt vẫn đi theo template.</div><div class="template-actions"><a href="templates/common-workflow.json" download="mau-chung.template.json" class="button">Tải mẫu chung</a><button id="exportWorkflow" class="button primary">Xuất template hiện tại</button><button id="importWorkflow" class="button">Nhập template JSON</button></div><p>Nhập mẫu chỉ áp dụng được vào dự án trống chưa có tài liệu hoặc thông tin hồ sơ; luôn có bước xem lại trước khi áp dụng.</p><p id="templateError" class="error" role="alert"></p>`);$('#exportWorkflow').onclick=()=>downloadTemplate(Workflow.toTemplate(state));$('#importWorkflow').onclick=()=>{const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('Template quá lớn (tối đa 2 MB).');const incoming=Workflow.fromTemplate(JSON.parse(await file.text()),definitions);const empty=state.nodes.every(n=>n.status==='missing'&&!n.files.length&&!n.code&&!n.date&&!n.note&&!n.issuer&&!n.startDate&&!n.dueDate&&!n.completedAt);if(!empty)throw Error('Hãy chọn một thư mục dự án mới, trống trước khi nhập template.');showModal('Xem lại template',`<p><b>${esc(incoming.name)}</b></p><p>${incoming.nodes.length} bước · ${incoming.nodes.reduce((a,n)=>a+n.dateRules.length,0)} quy tắc ngày</p><ul>${stageNames.map((name,i)=>'<li>'+name+': '+incoming.nodes.filter(n=>n.stage===i).length+' bước</li>').join('')}</ul><div class="notice">Áp dụng vào dự án trống “${esc(state.name)}”. Không tự tạo hồ sơ đã hoàn tất.</div><div class="modal-actions"><button class="button primary" id="applyWorkflow">Áp dụng template</button></div>`);$('#applyWorkflow').onclick=async()=>{const backup=structuredClone(state);incoming.name=state.name;incoming.code=state.code;state=incoming;if(await commitWorkflow(backup,'Áp dụng template quy trình')){$('#modal').close();toast('Đã áp dụng template')}};}catch(e){$('#templateError').textContent=e.message}};input.click()};}
render();
